from taf.gnb.oam.coam.admin.interfaces.admin_19b import ADMIN19B
from taf.gnb.oam.coam.admin.interfaces.admin_20a import ADMIN20A
from taf.gnb.oam.coam.admin.interfaces.admin_20b import ADMIN20B
from taf.gnb.oam.coam.admin.interfaces.admin_21a import ADMIN21A
from taf.gnb.oam.coam.admin.interfaces.admin_21b import ADMIN21B
from taf.gnb.oam.coam.admin.interfaces.admin_22r3 import ADMIN22R3
from taf.gnb.oam.coam.admin.exceptions import ReleaseNotSupported


class SupportedCaomAdminVersions(object):
    admin19b = ADMIN19B
    admin20a = ADMIN20A
    admin20b = ADMIN20B
    admin21a = ADMIN21A
    admin21b = ADMIN21B
    admin22r3 = ADMIN22R3


class CoamAdminProvider(object):
    @classmethod
    def get_coam_admin_interface(cls, api_client, release):
        coam_admin_interface = getattr(SupportedCaomAdminVersions, release.lower(), None)
        if not coam_admin_interface:
            error_message = 'This version {} is not supported'.format(coam_admin_interface)
            raise ReleaseNotSupported(error_message)
        coam_admin_obj = coam_admin_interface(api_client)

        return coam_admin_obj
